from pathlib import Path
import json,hashlib
BASE=Path(__file__).resolve().parent
ROOT=BASE.parents[1]
f=BASE/'fresh_content_audit.json';audit=json.loads(f.read_text())
CAM=ROOT/audit['campaign']/'generation'
def record(case,arm,display,boundary):
 p=CAM/case/arm/'repeat_01/result.json';d=json.loads(p.read_text());r={'case':display,'arm':'FlowPilot' if arm=='claude_flowpilot' else 'One-shot','result_path':str(p.relative_to(ROOT)),'result_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'reviewed_boundary':boundary,'positive_checks':[],'findings':[]};return r,d
def put(r):
 audit['reviewed_outcomes']=[x for x in audit['reviewed_outcomes'] if x['result_path']!=r['result_path']]+[r]
def check(r,desc,text,quote=None):
 row={'description':desc,'check':text}
 if quote:row['quote']=quote
 r['positive_checks'].append(row)
def finding(r,id,kind,fields,quotes,text):r['findings'].append({'id':id,'classification':kind,'source_paths':fields,'quotes':quotes,'check':text})
r,d=record('hydrogenolysis','claude_flowpilot','Hydrogenolysis','Actual final_design/result_report delivery. Blocked output is not replaced by a diagnostic candidate. Separate internal diagnostics explain failure only, and are not credited as a delivered executable design.')
check(r,'Delivery gate preserves failure status','Final status is blocked, parameters are null, streams/stages/process graph/recipe/operations withheld. The report does not present the incomplete graph as an executable experiment.')
finding(r,'H2-FP-DELIVERY','missing deliverable caused by lossy inventory mapping',['final_design.status','inventory_allocation.unresolved_requirements','diagnostic_topology.unit_operations[0].parameters','proposal.streams[0]'],[json.dumps(d['inventory_allocation']['unresolved_requirements'][0]),json.dumps(d['diagnostic_topology']['unit_operations'][0]['parameters']),json.dumps(d['proposal']['streams'][0]['contents'])],'The sole allocation failure is pump_a at 0.1 mL/min. The supplied pump is available, requested ID matches, 0.1 lies within 0.1–2 mL/min, the grid permits it, 21 bar is below its 40 bar rating, quantity is one and platform compatibility passes. Only _pump_material_compatible fails. Before mapping, this feed explicitly contains Methanol; after canonical solute rendering, contents contain only the full substrate name and solvent remains empty. The pump allowlist is [methanol,DMAOL]. Thus the failure reflects information loss at the mapper, not absent compatible hardware. An isolated unapplied patch and seven offline tests are saved under pump_material_repair. This does not change or rescore the blocked delivered result.')
finding(r,'H2-FP-INTERNAL-CONCENTRATION','diagnostic-only unresolved concentration inconsistency',['proposal.concentration_M','proposal.streams[0].concentration_M','proposal.decision_rationale'],['top-level concentration_M=0.1; stream A concentration_M=0.126'],'The intermediate candidate retains top-level 0.1 M versus 0.126 M in the actual feed. It is not a delivered executable recipe because release was blocked. A future repair should reconcile or clearly label aggregate/stream concentration rather than make these appear interchangeable.')
check(r,'Diagnostic gas and time arithmetic is internally coherent but unreleased','Intermediate feed supplies 0.126*0.1=0.0126 mmol/min substrate; 1 sccm at its explicitly recorded 273.15 K/1.01325 bar reference gives 0.0446175 mmol/min H2 and 3.5411 equivalents. MFC minimum 1 sccm is respected. At 60 C and 22.01325 bar absolute gas flow is 0.0561398 mL/min; gross liquid index=30 min, inlet index=3/(0.1+1)=2.727273 min, homogeneous channel index=3/(0.1+0.0561398)=19.2135 min. None is proof of packed-bed holdup or conversion. These checks explain the provisional state, not credit for delivered instructions.')
put(r)
r,d=record('photochemical_oxidation','claude_one_shot','Photochemical oxidation','raw_proposal; normalized proposal is not used as the generated answer')
p=d['raw_proposal']
check(r,'Chemical identity, stock ratio and available light preserved','The named sulfide substrate, 10 mol% photocatalyst, acetonitrile and 420 nm/1.5 W light match the supplied facts; 0.010/0.100=0.10 photocatalyst/substrate. Feed at 0.16 mL/min carries 0.016 mmol/min substrate. One liquid pump plus an air MFC feeds the two-input mixer. Temperature21 C and selected1 mLcoil/3barBPR match inventory.')
check(r,'Outlet pressure boundary explicitly placed correctly','Safety paragraph specifies gas-liquid separator downstream of BPR and upstream of atmospheric collector.',p['safety_flags'][3])
check(r,'Stock stabilization arithmetic closes','3mL/.16mL/min=18.75min, consistent with stated ~19min; this is a selected flushing quantity, not measured RTD.',p['pre_reactor_steps'][-1])
finding(r,'PHOTO-OS-GAS-VOLUME','contradictory gas-flow and pressure/time calculations',['raw_proposal.streams[1].gas_flow_actual_mL_min','raw_proposal.streams[1].gas_flow_notes','raw_proposal.reasoning_per_field.flow_rate_mL_min','raw_proposal.reasoning_per_field.residence_time_in_channel_min'],[str(p['streams'][1]['gas_flow_actual_mL_min']),p['streams'][1]['gas_flow_notes'],p['reasoning_per_field']['flow_rate_mL_min'],p['reasoning_per_field']['residence_time_in_channel_min']],'The same 0.8sccm air is represented as 0.04mL/min in-channel in the field and sum, and ~0.267mL/min in prose at3bar absolute; these cannot both describe the same reference and operating conditions. Conditional on nominal STP273.15K/1.01325bar and the prose operating3bar absolute at21C, ideal-gas conversion gives0.291mL/min, not0.04. At3barg it is~0.2175mL/min. The narrative alternates20%gas/62.5%gas and2.3/5/6.25min. 1*.8/.16=5, not6.25; an arbitrary25%margin changes the proposed target rather than physical holdup. Actual two-phase RTD needs evidence. The inlet field5min also does not equal standard-flow index1/(.16+.8)=1.04167min.')
finding(r,'PHOTO-OS-OXYGEN','gas-equivalent contradiction and possible double-counting of dissolved gas',['raw_proposal.streams[1].molar_equiv','raw_proposal.reasoning_per_field.gas_flow_sccm'],[str(p['streams'][1]['molar_equiv']),p['reasoning_per_field']['gas_flow_sccm']],'At22.4mL/mmol nominal standard gas,0.8*.21/22.4=.0075mmol/min O2; divided by.016mmol/min substrate gives.46875O2equiv. Total-air equivalents are2.232, so molar_equiv=1 fits neither basis. The statement correctly notices possible oxygen shortage but pressure-driven dissolution of this same feed is not an independent source of additional oxygen; any independently pre-dissolved oxygen would need a documented feed concentration. For sulfide+1/2O2→sulfoxide, ideal net atom balance is0.5O2eq, not the1eq implicitly called stoichiometric here. These facts alone do not predict conversion.')
finding(r,'PHOTO-OS-TIME-SCREEN','proposed follow-up times are liquid-volume indices mislabeled as exposure',['raw_proposal.post_reactor_steps[2]'],[p['post_reactor_steps'][2]],'1/.13=7.692 and1/.10=10min are liquid-only gross-volume indices; with a continuing gas co-feed these do not establish7.5 or10min actual residence time. Proposed gas-flow changes would change the gas fraction as well.')
finding(r,'PHOTO-OS-EVIDENCE','unverified literature assertions',['raw_proposal.literature_analogies'],p['literature_analogies'],'Named precedents and quantitative ranges have not been verified against papers in this read-only audit. No assertion of fabrication or independent precedent validation is made.')
r['serializer_differences']={k:{'raw':p.get(k),'normalized':d['proposal'].get(k)} for k in ('flow_rate_mL_min','residence_time_min','residence_time_inlet_min','residence_time_in_channel_min') if p.get(k)!=d['proposal'].get(k)}
put(r)
f.write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n')
print('Saved',len(audit['reviewed_outcomes']),'audits')
r,d=record('photochemical_oxidation','claude_flowpilot','Photochemical oxidation','Actual executable final_design and non-input result_report only. Internal council, historical candidate rationales and input data are not substituted for missing delivered operating details.')
p=d['final_design'];top=p['process_graph']['topology']
check(r,'Stock preparation and oxidant equivalents close','On10mL stock basis,1mmol substrate/.010L=.10M and.1mmol catalyst/.010L=.010M, preserving10mol%. Q=.01mL/min gives.001mmol/min substrate. Air.106727sccm/22.412722=.0047619mmol/min totalgas; O2 fraction.21 gives.001mmol/min and1activeO2equivalent. The explicit equivalent basis avoids confusing air with reactiveoxygen.',p['streams'][1]['molar_equiv_basis'])
check(r,'Numeric time indices and commissioning periods are explicitly distinguished','1/(.01+.106727)=8.566998min inlet/STP index. With the delivered actualgas.029018mL/min,1/(.01+.029018)=25.6292min channel index;3*(1/.01)=300min nominal liquid-volume commissioning interval and1/.01=100min samplinginterval are correctly calculated. The instructions require measuredsteadycomposition/RTD instead of treating these indices as measured contacttimes.')
check(r,'Hardware limits and pressure boundary respected in displayed graph','Liquid.01mL/min andair.106727sccm respect the pump/MFC minima. Reactor25C is a permitted inventory setting and3barBPR is available. Process edges putBPR before atmosphericcollector. Shielding/oxygenvent hazards are recognized and named inventory controls are identified.')
finding(r,'PHOTO-FP-LIGHT-MISSING','required reaction operating input absent despite executable status',['final_design.parameters.wavelength_nm','final_design.instrument_manifest','final_design.process_graph.topology.unit_operations','final_design.operating_procedure','result_report.stages[0].wavelength_nm'],['wavelength_nm: null',p['operating_procedure'][next(i for i,x in enumerate(p['operating_procedure']) if x['step_id']=='PHOTO-LIGHT-ENCLOSURE')]['instruction']],'The protocol requires1.5W irradiation near420nm. Finaloutput contains no420nm value, no light_photo_420 assignment, no lamp operation and no irradiation-start instruction. The selected coil names photochemistry, and shielding is generic, but neither specifies the required energyinput. Presence of the lamp in the supplied inventory does not itself make it a selected/operated device. Finalcontract passes, so this is a genuine delivered omission missed by automated validation.')
finding(r,'PHOTO-FP-GAS-TEMPERATURE','minor state inconsistency in channel calculation',['final_design.parameters.temperature_C','final_design.streams[1].reasoning','final_design.parameters.residence_time_in_channel_min'],[str(p['parameters']['temperature_C']),p['streams'][1]['reasoning']],'Selectedreactor temperature is25C, but the reported in-channel gasvolume is evaluated at21C. At the same4.01325barabsolute, correcting294.15K→298.15K givesgas~.0294123mL/min andhomogeneouschannelindex~25.3728min, ratherthan25.6292. A separatelydefined21Cinjection temperature could be appropriate at the inlet, but is not the25Creactor state used for an in-channelindex. Actualphaseholdup remains unmeasured.')
finding(r,'PHOTO-FP-VENT-TOPOLOGY','vent hardware listed but not placed on explicit process graph',['final_design.instrument_manifest','final_design.process_graph.topology.streams','final_design.safety.controls'],[json.dumps(top['streams'][-1]),next(x['instruction'] for x in p['operating_procedure'] if x['step_id']=='OXYGEN-ORGANIC-VENT')],'The ventedseparator is attached as safety equipment, but processedges runBPR→collector directly. The instruction routesoffgas to a compatiblevent without locating separator relative toBPR/collector. This is a placement ambiguity, not a claim that a vent exists upstream of pressurecontrol or that the ventedcollector alone cannotfunction.')
finding(r,'PHOTO-FP-PROCEDURE-SPECIFICITY','procedure delegates unresolved operating details',['final_design.operating_procedure'],[next(x['instruction'] for x in p['operating_procedure'] if x['step_id']=='GENERAL-EMERGENCY-STOP'),next(x['instruction'] for x in p['operating_procedure'] if x['step_id']=='NORMAL-SHUTDOWN')],'Emergency feed-stopsequence and compatibleflushamount/duration are left for the operator to define. The finaloutput gives concrete feedpreparation and collectiontimes, but generic checklist instructions do not by themselves constitute a fully specified startup/shutdown program. No laboratoryfailure probability is inferred.')
put(r);f.write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n');print('Saved',len(audit['reviewed_outcomes']),'audits')
r,d=record('cuaac','claude_one_shot','CuAAC','raw_proposal with all narrative and stage_parameters retained; normalized serialization not used as the generated answer')
p=d['raw_proposal']
check(r,'Feed stoichiometry and catalyst placement preserved','The liquid stock retains benzylazide0.25M andphenylacetylene0.275M, giving1.10equivalents. At.20mL/min these deliver.050/.055mmol/min. Cu/C stays in the assigned cartridge, not in the liquid stock. No separate mixer is introduced where none is available.')
check(r,'Gross-volume index and primary inventory settings close','0.3mL/.2mL/min=1.5min gross packed-bed-volume index. The supplied cartridge is0.3mL, pump permits.1–3mL/min, heater permits150C, and BPR20bar matches its sole setpoint. The vented collector is explicitly downstream ofBPR.')
check(r,'Conditioning and collection calculations mostly close','2mL/.2=10min conditioning,3*.3=.9mL discard and.9/.2=4.5min,10min*.2=2mL collected. The15min reagent step yields3mL, versus2.9mL described discard+collection; the0.1mL difference is consistent with approximate timing rather than necessarily a meaningful material loss.')
finding(r,'CU-OS-FLUSH','procedure/stage-table numerical contradiction',['raw_proposal.post_reactor_steps[3]','raw_proposal.stage_parameters[3]'],[p['post_reactor_steps'][3],json.dumps(p['stage_parameters'][3])],'The written flush is3mL at.2mL/min, requiring15min. The stage table instead allocates5min, delivering1mL. The operator has two different flush specifications.')
finding(r,'CU-OS-PACKED-BED-TIME','self-inconsistent void-volume explanation',['raw_proposal.residence_time_basis','raw_proposal.reasoning_per_field.residence_time_min'],[p['residence_time_basis'],p['reasoning_per_field']['residence_time_min']],'The basis paragraph calculates assumed0.15mL voidvolume/.1mL/min=1.5min, although the actual selected flow is.2mL/min. The later reasoning correctly calculates.15/.2=.75min. The displayed1.5min is valid as fullbedvolume/flow, but cannot simultaneously be the same50%-void liquid exposure. Neither assumed50%voidage nor a conservative upper index proves actual contacttime.')
finding(r,'CU-OS-UNLISTED-N2','preparation requires unavailable-in-input gas supply',['raw_proposal.pre_reactor_steps[0]','input_inventory.gas_hardware'],[p['pre_reactor_steps'][0],'gas_hardware: []'],'The mandatory5minN2sparge requires a nitrogen source that is not included in the supplied inventory, and this exception is not flagged as a required addition. This does not assert that the actual laboratory lacks nitrogen.')
finding(r,'CU-OS-EVIDENCE','unverified compatibility and literature certainty',['raw_proposal.mixing_order_reasoning','raw_proposal.safety_flags[5]','raw_proposal.literature_analogies'],[p['mixing_order_reasoning'],p['safety_flags'][5]],'Premix stability and absence of solublecopper are expressed as confirmed rather than explicitly bounded assumptions. Named papers, vaporpressure and thermalstability claims were not independently verified in this audit, so they are not treated here as established evidence or as proven fabrications.')
r['serializer_differences']={k:{'raw':p.get(k),'normalized':d['proposal'].get(k)} for k in ('flow_rate_mL_min','residence_time_min','residence_time_inlet_min','residence_time_in_channel_min') if p.get(k)!=d['proposal'].get(k)}
put(r);f.write_text(json.dumps(audit,ensure_ascii=False,indent=2)+'\n');print('Saved',len(audit['reviewed_outcomes']),'audits')
r,d=record('cuaac','claude_flowpilot','CuAAC','Actual blocked final_design/result_report. Internal candidate and source model response are inspected only to diagnose release failure; neither substitutes for a delivered experiment.')
p=d['final_design']
check(r,'Failed approval and allocation are exposed','Final status is blocked, with no executable parameters, streams, graph, recipe or operating procedure. Cu/C remains identified as a stationary component, rather than a supplied liquid charge.')
finding(r,'CU-FP-NO-DELIVERABLE','no approved candidate and incomplete inventory allocation',['final_design.consistency.issues','inventory_allocation.unresolved_requirements'],[json.dumps(p['consistency']['issues']),json.dumps(d['inventory_allocation']['unresolved_requirements'])],'Two distinct failure classes are retained. No candidate passed inventory realization/council approval, and pump_a remains unassigned. The pump can supply0.1mL/min at20bar, but its only declared compatible medium is acetone. The intermediate feed explicitly includes acetone, while canonical topology contents retain only benzyl azide and phenylacetylene and leave solvent empty. This reproduces the same medium-loss mapper bug as H2. A pump-only repair does not by itself remove the separate missing-approval failure.')
finding(r,'CU-FP-DEFAULTED-SCIENTIFIC-INPUT','diagnostic evidence of a format-induced loss before review',['llm_events.jsonl:event2.response_text.proposal','proposal.temperature_C','proposal.concentration_M','proposal.streams[0].concentration_M'],['Raw nested model proposal: temperature_C=150.0; flow_rate_mL_min=1.0; concentration_M=0.25; reactor_volume_mL=0.3.','Post-parser diagnostic proposal: temperature_C=25.0; top-level concentration_M=0.1; feed A concentration_M=0.25.'],'The original raw translation response is wrapped in a proposal envelope. Production parsing silently defaults fields at the envelope root instead of extracting the nested proposal. The resulting25C temperature is not evidence that the model chose room-temperature CuAAC. Later reconstruction restores .25/.275M feed components from chemistry, leaving .1M at top level. The loss is documented by an exact offline parser replay in wrapper_loss_comparison.json. No diagnostic numbers were substituted in scoring or final delivery.')
check(r,'Intermediate stoichiometry and gross time are reconstructable but unreleased','The diagnostic feed contains0.25M benzyl azide and0.275M phenylacetylene, which preserve1.1equivalents. At0.1mL/min these deliver0.025 and0.0275mmol/min;0.3mL cartridge/0.1mL/min=3min nominal empty-bed time. These are arithmetic checks of the incomplete candidate, not credit for a delivered recipe or evidence of conversion.')
put(r)
audit['status']='complete_for_six_original_fresh_outputs'
audit['interpretation_caution']='The shared final-output envelope was inserted into the scientific objective by the benchmark harness. All three fresh FlowPilot translation responses adopted that envelope, which the existing parser silently converted to defaults. Three immediately preceding practical FlowPilot responses and three original manuscript examples were flat and retained their scientific fields. This six-output campaign is therefore a format-confounded diagnostic, not a clean estimate of the architecture effect. Its outcomes and original scores must remain preserved; no favorable diagnostic reconstruction replaces them. A separately registered harness-only follow-up is required.'
